import Root from "./1Adding Interactivity/5UpdatingArrays"
import Sub from "./subReLearn"
import "./ReLearn.css"

export default function () {
  return (
    <>
    <Screen/>
    </>
  );
}

import { useState } from "react"
import { useImmer } from "use-immer"

const initialNum = 0
export function Screen() {
  const [num, setNum] = useImmer(initialNum)
  const [otherNum, setOtherNum] = useImmer(initialNum)
  function change() {
    let numbre = num
    numbre = 10
    setNum(numbre)
  }
  function otherChange() {
    let numbre = num
    numbre = 10
    setNum(numbre)
  }
  return (
    <>
    <Elem content={num} func={change}/>
    <Elem content={otherNum} func={change}/>
    </>
  );
}

function Elem({content, func}) {
  return <>{content} <button onClick={func}>click</button><br/></>
}


// http://localhost:3000
